<?php
namespace App\Http\Controllers; use App\Models\{Empleado,TrainingSession,TrainingTopic}; use App\Services\TrainingSessionService; use Illuminate\Http\Request;
class TrainingInductionController extends Controller { public function index(){ $company=auth()->user()->company_id;$employees=Empleado::where('company_id',$company)->active()->whereNotNull('fecha_ingreso')->get()->filter(fn($e)=>!TrainingSession::forCompany($company)->where('training_type','induction')->where('status','closed')->whereHas('attendanceEvent.participants',fn($q)=>$q->where('employee_id',$e->id))->exists());return view('training.inductions.index',compact('employees'));} public function store(Request$r,TrainingSessionService$s){$d=$r->validate(['employee_ids'=>'required|array|min:1','employee_ids.*'=>'exists:empleados,id','scheduled_start_at'=>'required|date','scheduled_end_at'=>'required|date|after:scheduled_start_at','instructor_employee_id'=>'required|exists:empleados,id','location'=>'nullable|string|max:255']);$company=$r->user()->company_id;$ids=Empleado::where('company_id',$company)->active()->whereIn('id',$d['employee_ids'])->pluck('id')->all();abort_if(!$ids,422,'No se encontraron empleados válidos.');$topic=TrainingTopic::availableTo($company)->where('training_type','induction')->where('is_active',true)->first();$session=$s->create(['training_topic_id'=>$topic?->id,'title'=>'Inducción SG-SST','description'=>'Inducción general y específica previa o asociada al ingreso.','training_type'=>'induction','induction_scope'=>'general','scheduled_start_at'=>$d['scheduled_start_at'],'scheduled_end_at'=>$d['scheduled_end_at'],'planned_duration_minutes'=>max(1,\Carbon\Carbon::parse($d['scheduled_start_at'])->diffInMinutes(\Carbon\Carbon::parse($d['scheduled_end_at']))),'modality'=>'presential','location'=>$d['location']??null,'instructor_type'=>'internal','instructor_employee_id'=>$d['instructor_employee_id'],'audience_type'=>'specific_employees','audience_description'=>'Nuevos ingresos seleccionados','specific_employee_ids'=>$ids,'requires_attendance'=>true,'requires_signature'=>true,'requires_material'=>true,'requires_execution_report'=>true],$company,$r->user()->id);$s->schedule($session,$r->user()->id);return redirect()->route('training.sessions.show',$session)->with('success','Inducción programada.');} }
